-- ============================================================
-- SEAAL PROJECT - Base de données complète
-- Base principale : usersdb
-- Base secondaire : test_seaal
-- ============================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";
SET NAMES utf8mb4;

-- ============================================================
-- BASE DE DONNÉES: usersdb
-- ============================================================
CREATE DATABASE IF NOT EXISTS `usersdb` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `usersdb`;

-- ------------------------------------------------------------
-- TABLE: users
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(50) NOT NULL,
  `password` varchar(255) NOT NULL,
  `picture` MEDIUMBLOB DEFAULT NULL,
  `autorisation` varchar(50) DEFAULT 'non compléte',
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- Mises à jour colonnes si table déjà existante
ALTER TABLE `users` MODIFY COLUMN `picture` MEDIUMBLOB;
ALTER TABLE `users` ADD COLUMN IF NOT EXISTS `autorisation` VARCHAR(50) DEFAULT 'non compléte';
UPDATE `users` SET `autorisation` = 'non compléte' WHERE `autorisation` IS NULL OR `autorisation` = '';

-- ------------------------------------------------------------
-- TABLE: disponibilite
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `disponibilite` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nom` VARCHAR(100) NOT NULL,
    `description` TEXT,
    `autorisation` VARCHAR(50) DEFAULT 'non compléte',
    `last_backup_time` DATETIME DEFAULT NULL,
    `last_backup_user` VARCHAR(100) DEFAULT 'Inconnu',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    `updated_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

ALTER TABLE `disponibilite` ADD COLUMN IF NOT EXISTS `last_backup_time` DATETIME DEFAULT NULL;
ALTER TABLE `disponibilite` ADD COLUMN IF NOT EXISTS `last_backup_user` VARCHAR(100) DEFAULT 'Inconnu';

