CREATE TABLE IF NOT EXISTS `employes` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `nom` VARCHAR(100),
    `prenom` VARCHAR(100),
    `email` VARCHAR(150),
    `poste` VARCHAR(100),
    `date_embauche` DATE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

